const raw = await Promise.all(commands.map(({args}) => tools.exec_command(args)));
function files(output) {
  const found = new Set();
  for (const line of output.split("\n")) {
    const match = line.match(/(?:^|\s)((?:packages|scripts|tests)\/[^\s]+\.test\.(?:ts|mjs))/);
    if (match) found.add(match[1]);
    const cliMatch = line.match(/(?:^|\s)(src\/[^\s]+\.test\.ts)/);
    if (cliMatch) found.add(`packages/cli/${cliMatch[1]}`);
  }
  return [...found].sort();
}
const selections = Object.fromEntries(commands.map((c, i) => [c.name, files(raw[i].output)]));
function intersection(a, b) {
  const bs = new Set(b);
  return a.filter(x => bs.has(x));
}
text(JSON.stringify({
  counts: Object.fromEntries(Object.entries(selections).map(([k,v]) => [k, v.length])),
  unit_contract_overlap: intersection(selections.unit, selections.contract),
  unit_stdio_overlap: intersection(selections.unit, selections.stdio),
  unit_cli_overlap: intersection(selections.unit, selections.cli),
  contract_stdio_overlap: intersection(selections.contract, selections.stdio),
  selections,
  raw_stderr_or_notices: Object.fromEntries(commands.map((c, i) => [c.name, raw[i].output.split("\n").filter(l => !files(l).length && l.trim()).slice(0, 10)]))
}, null, 2));

