    workdir: "/root/.codex/worktrees/hevy-architecture-improvement-scan-20260807",
    yield_time_ms: 30000,
    max_output_tokens: 30000
  });
  const lines = r.output.split("\n");
  summaries[lane] = {
    exit_code: r.exit_code,
    wall_time_seconds: r.wall_time_seconds,
    evidence: lines.filter(line =>
      /Test Files|Tests\s|Duration|ELAPSED_SECONDS|failed|passed|npm error/i.test(line)
    ).slice(-12)
  };
}
text(JSON.stringify(summaries, null, 2));

